const arr = ['apple', 'banana', 'cherry'];

// Boolean check:
arr.includes('banana');   // true
arr.includes('pear');     // false

// Get the index (-1 when missing):
arr.indexOf('banana');    // 1

// Custom predicate (e.g. objects):
arr.some(item => item.startsWith('b'));  // true

// Fast repeated lookups — Set:
const seen = new Set(arr);
seen.has('banana');       // true, O(1)

// in an if statement:
if (arr.includes('banana')) {
  console.log('found');
}

// Strict conversion:
Number('42');      // 42
Number('42px');    // NaN  — whole string must be numeric

// Prefix parsing (ignores trailing junk):
parseInt('42px');  // 42
parseInt('0x10');  // 16  (hex prefix)

// Unary plus (same as Number):
+'42';             // 42

// Decimals:
parseFloat('3.14');  // 3.14

// Robust pattern with validation:
const num = Number(userInput);
if (Number.isNaN(num)) {
  // handle invalid input instead of silently proceeding
}

// Classic index loop:
for (let i = 0; i < 5; i++) {
  console.log(i);
}

// Print 1 to 10:
for (let i = 1; i <= 10; i++) {
  console.log(i);
}

// for...of over an array:
for (const item of ['a', 'b', 'c']) {
  console.log(item);
}

// forEach with index:
['a', 'b', 'c'].forEach((item, idx) => {
  console.log(idx, item);
});

// Break out of a loop:
for (let i = 0; i < 100; i++) {
  if (i === 5) break;
  console.log(i);
}

const text = 'The quick brown fox';

text.includes('quick');            // true
text.includes('cat');              // false

// Case-insensitive check:
text.toLowerCase().includes('QUICK'.toLowerCase());  // true

// Position (indexOf):
text.indexOf('brown');             // 10
text.indexOf('missing');           // -1

// Regex (search):
text.search(/br[o]+wn/);           // 10

// Starts / ends with:
text.startsWith('The');            // true
text.endsWith('fox');              // true
